                    substr(hex(randomblob(2)), 2) || '-' ||
                    hex(randomblob(6))
                  )
                )
                WHERE "id" = NEW."id";
              END;

CREATE TRIGGER "trg_invoice_items_uuid"
              AFTER INSERT ON "invoice_items"
              WHEN NEW."uuid" IS NULL
              BEGIN
                UPDATE "invoice_items" SET "uuid" = (
                  SELECT lower(
                    hex(randomblob(4)) || '-' ||
                    hex(randomblob(2)) || '-4' ||
                    substr(hex(randomblob(2)), 2) || '-' ||
                    substr('89ab', abs(random()) % 4 + 1, 1) ||
                    substr(hex(randomblob(2)), 2) || '-' ||
                    hex(randomblob(6))
